const fs = require('fs');
const dataPath = 'E:\\RainTube\\config\\pipeline_output.json';

let data;
try {
  const raw = fs.readFileSync(dataPath, 'utf8');
  data = JSON.parse(raw);
  console.log('Datos cargados desde pipeline_output.json');
  console.log('Tema:', data.tema?.tema);
  console.log('Videos:', data.archivos_video?.length);
  console.log('Audios:', data.archivos_audio?.length);
} catch(e) {
  throw new Error('No se encontraron datos del WF1. Ejecuta primero el Workflow 1. Error: ' + e.message);
}

return [{ json: data }];

const data = $input.first().json;
const fs = require('fs');
const path = require('path');

const carpetaVideos = data.carpeta_videos;
const timestamp = data.timestamp;
const processingDir = `E:\\RainTube\\processing\\${timestamp}`;

if (!fs.existsSync(processingDir)) {
  fs.mkdirSync(processingDir, { recursive: true });
}

// Crear archivo de lista para FFmpeg concat
const archivosVideo = data.archivos_video.map(a => a.path);
const listContent = archivosVideo.map(f => `file '${f.replace(/\\/g, '/')}'`).join('\n');
const listPath = path.join(processingDir, 'videos_list.txt');
fs.writeFileSync(listPath, listContent);

return [{ json: {
  ...data,
  processing_dir: processingDir,
  list_path: listPath,
  archivos_video_count: archivosVideo.length
} }];

const { execSync } = require('child_process');
const ffmpeg = 'C:\\Users\\Jowy\\AppData\\Local\\Microsoft\\WinGet\\Packages\\Gyan.FFmpeg_Microsoft.Winget.Source_8wekyb3d8bbwe\\ffmpeg-8.0.1-full_build\\bin\\ffmpeg.exe';
