const cmd = `"${ffmpeg}" -y -f concat -safe 0 -i "${listPath}" -vf "scale=1920:1080:force_original_aspect_ratio=decrease,pad=1920:1080:(ow-iw)/2:(oh-ih)/2,setsar=1" -c:v libx264 -preset medium -crf 20 -an -r 30 "${outputPath}"`;
